namespace sv_98230ef77c1046bf967c211909c2c9f8.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "warehouse-a";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_98230ef77c1046bf967c211909c2c9f8.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Scoped lifetime ensures each user circuit has independent state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling. Uses reference counting so multiple components can subscribe
    /// but only one timer runs.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Stop polling when a subscriber leaves. Timer stops when last subscriber disconnects.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Force an immediate refresh (e.g. when warehouse changes).
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is not null && await _timer.WaitForNextTickAsync(ct))
                {
                    await RefreshAsync();
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void OnWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

