@inject sv_98230ef77c1046bf967c211909c2c9f8.Services.WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: 200px;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in sv_98230ef77c1046bf967c211909c2c9f8.Services.WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

